package com.estateflow.service;
import com.estateflow.dao.*;import com.estateflow.exception.*;import com.estateflow.model.*;import com.estateflow.model.enums.MaintenancePriority;import com.estateflow.security.Authorizer;import com.estateflow.support.TestAuth;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class WorkOrderServiceTest{
 private static final Clock CLOCK=Clock.fixed(Instant.parse("2026-10-10T00:00:00Z"),ZoneOffset.UTC);private final WorkOrderDao dao=mock(WorkOrderDao.class);private final PropertyDao properties=mock(PropertyDao.class);private final VendorDao vendors=mock(VendorDao.class);private final MaintenanceService maintenance=mock(MaintenanceService.class);private final ExpenseService expenses=mock(ExpenseService.class);
 private WorkOrderService service(Authorizer auth){return new WorkOrderService(dao,properties,vendors,maintenance,expenses,new PassThroughTransactionManager(),AuditService.noop(),CLOCK,auth);}
 @Test void createsDraftForActivePropertyAndAuditsThroughService() throws Exception{when(dao.isAvailable()).thenReturn(true);Property p=new Property();p.setPropertyId(5L);when(properties.findById(5L)).thenReturn(Optional.of(p));WorkOrder saved=new WorkOrder(9L,5L,null,null,null,"Repair roof",null,MaintenancePriority.HIGH,LocalDate.of(2026,10,12),WorkOrderStatus.DRAFT,new BigDecimal("500"),null,null,1L,null,null,null);when(dao.insert(any())).thenReturn(saved);WorkOrder input=new WorkOrder(null,5L,null,null,null," Repair roof ",null,MaintenancePriority.HIGH,LocalDate.of(2026,10,12),null,new BigDecimal("500"),null,null,null,null,null,null);assertEquals(9L,service(TestAuth.admin()).create(input).id());verify(dao).insert(argThat(w->w.status()==WorkOrderStatus.DRAFT&&w.title().equals("Repair roof")));}
 @Test void completionUsesOptimisticTransitionAndValidatesActualCost() throws Exception{when(dao.isAvailable()).thenReturn(true);WorkOrder old=new WorkOrder(4L,5L,3L,6L,null,"Leak",null,MaintenancePriority.MEDIUM,null,WorkOrderStatus.IN_PROGRESS,null,null,null,1L,null,null,null);WorkOrder completed=new WorkOrder(4L,5L,3L,6L,null,"Leak",null,MaintenancePriority.MEDIUM,null,WorkOrderStatus.COMPLETED,null,new BigDecimal("40.00"),"Fixed",1L,null,null,LocalDateTime.now(CLOCK));when(dao.find(4L)).thenReturn(Optional.of(old),Optional.of(completed));when(dao.complete(eq(4L),eq(WorkOrderStatus.IN_PROGRESS),eq(new BigDecimal("40.00")),eq("Fixed"),any())).thenReturn(1);assertEquals(WorkOrderStatus.COMPLETED,service(TestAuth.admin()).transition(4L,WorkOrderStatus.COMPLETED,new BigDecimal("40.00"),"Fixed").status());verify(dao).complete(eq(4L),eq(WorkOrderStatus.IN_PROGRESS),eq(new BigDecimal("40.00")),eq("Fixed"),any());}
 @Test void refusesInvalidTransitionAndViewerWritesBeforeDao(){when(dao.isAvailable()).thenReturn(true);WorkOrder closed=new WorkOrder(4L,5L,null,6L,null,"Leak",null,MaintenancePriority.MEDIUM,null,WorkOrderStatus.COMPLETED,null,null,null,1L,null,null,null);when(dao.find(4L)).thenReturn(Optional.of(closed));assertThrows(BusinessRuleException.class,()->service(TestAuth.admin()).transition(4L,WorkOrderStatus.IN_PROGRESS,null,null));verify(dao,never()).transition(anyLong(),any(),any(),any(),any());reset(dao);WorkOrder input=new WorkOrder(null,5L,null,null,null,"title",null,MaintenancePriority.LOW,null,null,null,null,null,null,null,null,null);assertThrows(AuthorizationException.class,()->service(TestAuth.as(com.estateflow.model.enums.Role.VIEWER)).create(input));verifyNoInteractions(dao);}
 @Test void invalidCostIsRejected(){when(dao.isAvailable()).thenReturn(true);WorkOrder input=new WorkOrder(null,5L,null,null,null,"Bad amount",null,MaintenancePriority.LOW,null,null,new BigDecimal("1.001"),null,null,null,null,null,null);assertThrows(ValidationException.class,()->service(TestAuth.admin()).create(input));}
}
